# Golden fixtures generated by the independent exact fixed-r Python evaluator.
library(SUNLouvainPath)

make_snn <- function(n, edges) {
    cells <- paste0("c", seq_len(n))
    counts <- Matrix::sparseMatrix(i = rep(1L, n), j = seq_len(n), x = rep(1, n),
        dims = c(1L, n), dimnames = list("placeholder", cells))
    graph <- Matrix::sparseMatrix(i = c(edges[, 1], edges[, 2]), j = c(edges[, 2], edges[, 1]),
        x = rep(edges[, 3], 2L), dims = c(n, n), dimnames = list(cells, cells))
    obj <- SeuratObject::CreateSeuratObject(counts)
    obj[["RNA_snn"]] <- SeuratObject::as.Graph(graph)
    obj
}

# All four start trajectories remain fixed across r=13/14; the first and
# fourth starts have (directed internal weight, squared volumes) (26,906)
# and (34,1354). Their scores cross at 52*(34-26)/(1354-906) = 13/14.
edges <- cbind(c(1,1,1,1,2,3,3,3,3,4,4), c(2,4,6,7,5,4,5,6,7,6,7),
               c(4,1,4,1,4,2,4,2,2,1,1))
control <- list(algorithm=1L, modularity.fxn=1L, n.start=4L, n.iter=2L,
                random.seed=0L, group.singletons=FALSE)
obj <- make_snn(7L, edges)
get_raw <- function(workers) {
    result <- EnumerateLouvain(obj, "RNA_snn", weights="stored", split_points=numeric(),
        r_max=1, workers=workers, louvain_engine="seurat", seurat.control=control, max_clusters=Inf)
    SeuratObject::Tool(result, slot="SUNLouvainPath")$raw
}
raw <- get_raw(1L)
left <- raw$intervals[raw$intervals$upper == "13/14" & !raw$intervals$upper_closed, ]
point <- raw$intervals[raw$intervals$lower == "13/14" & raw$intervals$lower_closed, ]
stopifnot(nrow(left) == 1L, nrow(point) == 1L,
          identical(as.integer(raw$partitions[[left$partition]]), c(2L,2L,1L,1L,1L,2L,1L)),
          identical(as.integer(raw$partitions[[point$partition]]), c(3L,2L,1L,1L,2L,3L,1L)))

# Certifies a zero-gain dyadic edge at its exact boundary. Native double
# Seurat 5.5 evaluates a positive residual for this edge on the test system.
control$n.start <- control$n.iter <- 1L
obj <- make_snn(2L, matrix(c(1,2,49/64),nrow=1L))
result <- EnumerateLouvain(obj, "RNA_snn", weights="stored", workers=1L, r_max=2,
    louvain_engine="seurat", seurat.control=control, max_clusters=Inf)
raw <- SeuratObject::Tool(result, slot="SUNLouvainPath")$raw
point <- raw$intervals[raw$intervals$lower == "2" & raw$intervals$upper == "2", ]
stopifnot(nrow(point)==1L, point$lower_closed, point$upper_closed,
          identical(as.integer(raw$partitions[[point$partition]]), c(1L,2L)))
